/// Describes key conditions of the flowing well during a production well test.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
#[energyml(
    package = "prodml",
    version = "2.3",
    xml_name = "WellFlowingCondition"
)]
pub struct WellFlowingCondition {
    /// The choke diameter.
    #[energyml(elem, xml_name = "ChokeOrificeSize")]
    pub choke_orifice_size: Option<energyml_eml_2_3::LengthMeasure>,

    /// The measure depth datum for which the bottomhole pressure is reported.  This will later be converted to a TVD for reservoir engineering purpose.
    #[energyml(elem, xml_name = "BottomHolePressureDatumMd")]
    pub bottom_hole_pressure_datum_md: Option<energyml_eml_2_3::LengthMeasure>,

    /// The pressure at the bottom of the hole under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "BottomHoleStabilizedPressure")]
    pub bottom_hole_stabilized_pressure: Option<energyml_eml_2_3::PressureMeasure>,

    /// The temperature at the bottom of the hole under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "BottomHoleStabilizedTemperature")]
    pub bottom_hole_stabilized_temperature: Option<energyml_eml_2_3::ThermodynamicTemperatureMeasure>,

    /// The pressure at the casing head under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "CasingHeadStabilizedPressure")]
    pub casing_head_stabilized_pressure: Option<energyml_eml_2_3::AbstractPressureValue>,

    /// The temperature at the casing head under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "CasingHeadStabilizedTemperature")]
    pub casing_head_stabilized_temperature: Option<energyml_eml_2_3::ThermodynamicTemperatureMeasure>,

    /// The pressure at the tubing head under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "TubingHeadStabilizedPressure")]
    pub tubing_head_stabilized_pressure: Option<energyml_eml_2_3::AbstractPressureValue>,

    /// The temperature at the tubing head under stabilized conditions (typically at the end of the flowing period).
    #[energyml(elem, xml_name = "TubingHeadStabilizedTemperature")]
    pub tubing_head_stabilized_temperature: Option<energyml_eml_2_3::ThermodynamicTemperatureMeasure>,

    /// The fluid level achieved in the well. The value is given as length units from the well vertical datum.
    #[energyml(elem, xml_name = "FluidLevel")]
    pub fluid_level: Option<energyml_eml_2_3::LengthMeasure>,

    /// The lowest usable water depth as measured from the surface. See TxRRC H-15.
    #[energyml(elem, xml_name = "BaseUsableWater")]
    pub base_usable_water: Option<energyml_eml_2_3::LengthMeasure>,

}

